// Parse Gemini's style profile output and merge with the brief
const styleText = $input.first().json.candidates[0].content.parts[0].text;
const styleProfile = JSON.parse(styleText);
const payloads = $('Prepare Image Payloads').first().json;

return [{
  json: {
    brief: payloads.brief,
    style_profile: styleProfile,
    style_profile_json_string: JSON.stringify(styleProfile),
    logo_base64: payloads.logo_base64,
    logo_mime: payloads.logo_mime
  }
}];

// Read the captions response by node name, not from $input
let response;
try {
  response = $('Gemini: Generate Captions').first().json;
} catch (e) {
  throw new Error('Gemini: Generate Captions has not run in this execution. Run the workflow from the trigger, not this node alone.');
}

if (!response.candidates || !response.candidates[0]) {
  throw new Error(`Gemini Captions failed: ${JSON.stringify(response).slice(0, 500)}`);
}

// Gemini sometimes wraps JSON in ```json fences despite instructions
const captionText = response.candidates[0].content.parts[0].text
  .replace(/^```(?:json)?\s*/i, '')
  .replace(/```\s*$/, '')
  .trim();
const captions = JSON.parse(captionText);

const brief = $("Read Today's Brief").first().json;

// ─── Hashtags from the sheet ───────────────────────────────────────────────
const hashtags = String(brief.hashtags || '')
  .split(/[\s,]+/)
  .map(t => t.trim())
  .filter(Boolean)
  .map(t => (t.startsWith('#') ? t : `#${t}`))
  .join(' ');

const withTags = (text) => {
  const clean = String(text || '').trim();
  return hashtags ? `${clean}\n\n${hashtags}` : clean;
};

// ─── Image source (OpenAI or Nano Banana) ──────────────────────────────────
const imageModel = brief.image_model || 'nano_banana';

const imageNode = imageModel === 'openai'
  ? $('Extract Gen openai Image').first().json
  : $('Extract Gen Gemini Image').first().json;

const uploadNode = $('Upload Image to Drive').first().json;
const publicUrl = `https://drive.google.com/uc?export=view&id=${uploadNode.id}`;

// ─── Output ────────────────────────────────────────────────────────────────
return [{
  json: {
    row_number: imageNode.brief.row_number,
    'post#': brief['post#'],
    date: imageNode.today,
    primary_subject: imageNode.brief.primary_subject,
    generated_image_url: publicUrl,
    instagram_caption: withTags(captions.instagram_caption),
    facebook_caption: withTags(captions.facebook_caption),
    alt_text: captions.alt_text,
    hashtags,
    style_profile_json: imageNode.style_profile_json_string,
    image_model: imageModel,
    status: 'generated'
  }
}];

const input = $input.first().json;
const brief = input.brief || {};

// ─── Style profile from Gemini (nested inside style_profile) ───────────────
const styleProfile     = input.style_profile || {};
const extracted        = styleProfile.extracted_style || {};
const creativeUpgrades = styleProfile.creative_upgrades || {};
const designDirection  = styleProfile.final_design_direction || '';

// ─── Text cleaner: strip emojis and double quotes that confuse image models ─
function clean(text) {
  if (!text) return '';
  return String(text)
    .replace(/[\u{1F000}-\u{1FFFF}]/gu, '')
    .replace(/[\u{2600}-\u{27BF}]/gu, '')
    .replace(/["“”]/g, "'")
    .replace(/\s+/g, ' ')
    .trim();
}

// ─── Values from the sheet, with YOUR_BRAND fallbacks ─────────────────────────
const topicType      = clean(brief.topic_type)      || 'YOUR_DEFAULT_TOPIC';
const headline       = clean(brief.primary_subject) || 'YOUR_DEFAULT_HEADLINE';
const targetAudience = clean(brief.target_audience) || 'YOUR_DEFAULT_AUDIENCE';
const tone           = clean(brief.tone)            || 'YOUR_DEFAULT_TONE';
const cta            = clean(brief.cta)             || 'YOUR_DEFAULT_CTA';
const tagLine        = clean(brief.priceHook   || brief.price_hook)   || 'YOUR_DEFAULT_PRIMARY_HOOK';
const subLine        = clean(brief.outcomeHook || brief.outcome_hook) || 'YOUR_DEFAULT_OUTCOME_HOOK';

// Up to 2 short support chips (only if provided; never padded with blanks)
const supportRaw = Array.isArray(brief.supportPoints)
  ? brief.supportPoints
  : String(brief.supportPoints || brief.support_points || brief.key_facts || '')
      .split(/[,|\n]/);

const chips = supportRaw
  .map(clean)
  .filter(s => s && s.length <= 28)   // keep only short phrases that render well
  .slice(0, 2);

// ─── Style hints from the analysis ─────────────────────────────────────────
const palette = (creativeUpgrades.suggested_color_palette || extracted.color_palette || [])
  .filter(Boolean).join(', ');

const styleLines = [
  designDirection && `MASTER DESIGN DIRECTION: ${designDirection}`,
  palette && `Color palette: ${palette}`,
  creativeUpgrades.visual_trend && `Visual trend: ${creativeUpgrades.visual_trend}`,
  creativeUpgrades.layout_upgrade && `Layout idea: ${creativeUpgrades.layout_upgrade}`,
  creativeUpgrades.background_style && `Background: ${creativeUpgrades.background_style}`,
  creativeUpgrades.depth_technique && `Depth: ${creativeUpgrades.depth_technique}`,
  creativeUpgrades.typography_upgrade && `Typography: ${creativeUpgrades.typography_upgrade}`,
  creativeUpgrades.cta_upgrade && `CTA style: ${creativeUpgrades.cta_upgrade}`,
].filter(Boolean).join('\n');

// ─── Text block: only what will actually be rendered ──────────────────────
const textLines = [
  `- Headline (largest text): "${headline}"`,
  `- Sub-line (medium): "${subLine}"`,
  `- Small tag or sticker: "${tagLine}"`,
  ...chips.map((c, i) => `- Small chip ${i + 1}: "${c}"`),
  `- CTA button: "${cta}"`,
].join('\n');

// ─── Prompt ────────────────────────────────────────────────────────────────
const promptText = `
Create a square 1:1 social media post for Instagram and Facebook for YOUR_BRAND.

ABOUT YOUR_BRAND:
YOUR_PRODUCT_DESCRIPTION
Taglines: YOUR_TAGLINES
YOUR_BRAND_POSITIONING

POST TOPIC: ${topicType}
AUDIENCE: ${targetAudience}
TONE: ${tone}

VISUAL STORY:
- YOUR_SUBJECTS_AND_SCENE
- YOUR_DESIRED_FEELING
- YOUR_PHOTOGRAPHY_STYLE
- YOUR_OPTIONAL_BRAND_MOTIFS (max 1-2)
- YOUR_THINGS_TO_AVOID

${styleLines}

LOGO:
- The attached image is the exact YOUR_BRAND logo. Use it exactly as provided.
- Place it in the top-left or top-right corner with comfortable padding on a calm area with good contrast.
- Do NOT redraw, recolor, distort or recreate the logo, and do not add any other logo.

LAYOUT:
TOP     -> YOUR_BRAND logo in a corner
CENTER  -> Hero subject with the headline in clear open space (sky, wall, or soft panel)
BOTTOM  -> Sub-line, small tag/chips, and a rounded pill CTA button

TEXT TO RENDER (exactly as written, nothing else):
${textLines}

TEXT RULES:
- Render ONLY the text above. No extra words, captions, URLs, hashtags or labels.
- Spell every word exactly. Use sentence case as written; do not convert to all caps.
- Friendly, rounded, modern sans-serif typography, large and readable on a phone.
- Never place text over faces.

HARD CONSTRAINTS:
- Clean, uncluttered, plenty of breathing space.
- No watermarks, no gibberish text, no duplicated elements.
- Natural anatomy, correct hands and faces.
- Should feel like a warm, modern app brand post, not a sales flyer or brochure.
`.trim();

// ─── Gemini request body ───────────────────────────────────────────────────
const requestBody = {
  contents: [{
    parts: [
      { text: promptText },
      ...(input.logo_base64
        ? [{ inline_data: { mime_type: input.logo_mime || 'image/png', data: input.logo_base64 } }]
        : []),
    ],
  }],
  generationConfig: {
    responseModalities: ['IMAGE'],
    imageConfig: { aspectRatio: '1:1' },
  },
};

return [{
  json: {
    request_body: requestBody,
    brief,
    prompt_text: promptText,
    style_profile_json_string: input.style_profile_json_string,
    image_model: 'nano_banana',
  },
}];

const consolidated = $('Consolidate Results').first().json;
const imageUrl  = consolidated.generated_image_url;
const igCaption = consolidated.instagram_caption;
const fbCaption = consolidated.facebook_caption;
const altText   = consolidated.alt_text;
const subject   = consolidated.primary_subject;
const today     = consolidated.date;

// Resume URL of the Wait node in THIS execution
const resumeUrl = $execution.resumeUrl;
const sep = resumeUrl.includes('?') ? '&' : '?';
const approveUrl    = `${resumeUrl}${sep}action=approve`;
const regenerateUrl = `${resumeUrl}${sep}action=regenerate`;

const html = `
<!DOCTYPE html>
<html>
<head><meta charset="utf-8"></head>
<body style="font-family:-apple-system,BlinkMacSystemFont,'Segoe UI',Roboto,sans-serif;max-width:640px;margin:0 auto;padding:24px;background:#f5f5f7;color:#1d1d1f;">
  <div style="background:white;border-radius:12px;padding:28px;box-shadow:0 2px 8px rgba(0,0,0,0.04);">

    <h1 style="margin:0 0 4px;font-size:22px;">📣 YOUR_BRAND Daily Post Preview</h1>
    <p style="margin:0 0 20px;color:#6e6e73;font-size:14px;">${today} · ${subject}</p>

    <img src="${imageUrl}" alt="${altText}"
         style="width:100%;max-width:584px;border-radius:8px;display:block;margin-bottom:24px;" />

    <h3 style="margin:24px 0 8px;font-size:16px;">📷 Instagram Caption</h3>
    <div style="background:#f5f5f7;padding:16px;border-radius:8px;white-space:pre-wrap;font-size:14px;line-height:1.5;">${igCaption}</div>

    <h3 style="margin:24px 0 8px;font-size:16px;">👍 Facebook Caption</h3>
    <div style="background:#f5f5f7;padding:16px;border-radius:8px;white-space:pre-wrap;font-size:14px;line-height:1.5;">${fbCaption}</div>

    <h3 style="margin:24px 0 8px;font-size:16px;">♿ Alt Text</h3>
    <div style="background:#f5f5f7;padding:12px;border-radius:8px;font-size:13px;color:#6e6e73;">${altText}</div>

    <div style="margin-top:32px;text-align:center;">
      <a href="${approveUrl}"
         style="display:inline-block;background:#34c759;color:white;padding:14px 32px;border-radius:8px;text-decoration:none;font-weight:600;margin:6px;">
        ✓ Approve &amp; Schedule
      </a>
      <a href="${regenerateUrl}"
         style="display:inline-block;background:#ff3b30;color:white;padding:14px 32px;border-radius:8px;text-decoration:none;font-weight:600;margin:6px;">
        ↻ Regenerate
      </a>
    </div>

    <p style="margin-top:24px;text-align:center;color:#86868b;font-size:12px;">
      Approve schedules the post on Instagram + Facebook at the posting time in the sheet.<br/>
      Regenerate discards this version and creates a new one.<br/>
      These buttons only work for this run.
    </p>

  </div>
</body>
</html>
`;

return [{
  json: {
    to: 'you@example.com',
    subject: `📣 YOUR_BRAND Post Preview: ${subject}`,
    html,
    primary_subject: subject,
    date: today,
  }
}];

const brief = $("Read Today's Brief").first().json;

// ─── Sheet fields with YOUR_BRAND-friendly fallbacks ──────────────────────────
const topicType      = brief.topic_type      || 'YOUR_DEFAULT_TOPIC';
const primarySubject = brief.primary_subject || 'YOUR_DEFAULT_MAIN_MESSAGE';
const keyFacts       = brief.key_facts       || '';
const targetAudience = brief.target_audience || 'YOUR_DEFAULT_AUDIENCE';
const tone           = brief.tone            || 'YOUR_DEFAULT_TONE';
const cta            = brief.cta             || 'YOUR_DEFAULT_CTA';
const priceHook      = brief.priceHook   || brief.price_hook   || 'YOUR_DEFAULT_PRIMARY_HOOK';
const outcomeHook    = brief.outcomeHook || brief.outcome_hook || 'YOUR_DEFAULT_OUTCOME_HOOK';
const supportPoints  = brief.supportPoints || brief.support_points || keyFacts;

// ─── Brand context (from YOUR_DOMAIN) ─────────────────────────────────────
const brandContext = `
BRAND: YOUR_BRAND (YOUR_DOMAIN)
WHAT IT IS: YOUR_PRODUCT_DESCRIPTION
HOW IT WORKS: YOUR_HOW_IT_WORKS
TAGLINES: YOUR_TAGLINES
VALUES: YOUR_BRAND_VALUES
EMOTIONAL CORE: YOUR_EMOTIONAL_CORE
APP LINK: https://YOUR_APP_URL/
`.trim();

const promptText = `You are the social media copywriter for YOUR_BRAND. Write an Instagram caption and a Facebook caption for today's post.

${brandContext}

TODAY'S POST:
- Topic type: ${topicType}
- Main message: ${primarySubject}
- Key facts: ${keyFacts}
- Target audience: ${targetAudience}
- Tone: ${tone}
- Primary hook: ${priceHook}
- Outcome hook: ${outcomeHook}
- Proof points: ${supportPoints}
- CTA: ${cta}

RULES:
- Only state facts given above. Do NOT invent features, statistics, partners, prices or testimonials.
- Do NOT include any hashtags; they are added separately.
- Speak to the student directly ("you"). Warm and human, never corporate or salesy.
- Emojis allowed but sparing (max 3 per caption), e.g. YOUR_EMOJI_EXAMPLES.
- Use line breaks between short paragraphs for mobile readability.

INSTAGRAM CAPTION:
- Line 1: a scroll-stopping emotional hook tied to "${topicType}" (under 12 words, works before the "more" cut-off).
- Then 1-2 short paragraphs built on "${priceHook}" and "${outcomeHook}".
- End with the CTA and "Link in bio" (links are not clickable on Instagram).
- 300-600 characters total.

FACEBOOK CAPTION:
- Slightly more conversational and explanatory than Instagram; can briefly explain how YOUR_BRAND works.
- Opening line should invite engagement (a question or relatable moment).
- End with the CTA followed by the full link https://YOUR_APP_URL/ (clickable on Facebook).
- 400-800 characters total.

ALT TEXT:
- Under 125 characters, describing the generated post image for accessibility.

Output strict JSON only, no markdown fences:
{
  "instagram_caption": "...",
  "facebook_caption": "...",
  "alt_text": "..."
}`;

const requestBody = {
  contents: [{ parts: [{ text: promptText }] }],
  generationConfig: {
    temperature: 0.6,
    responseMimeType: "application/json",
  },
};

return [{ json: { request_body: requestBody } }];

const input = $input.first().json;
const brief = input.brief || {};
const styleProfile = input.style_profile || {};
const creativeUpgrades = input.creative_upgrades || {};
const designDirection = input.design_direction || '';

// ─── Pull all values from Google Sheet via brief ───────────────────────────

const topicType      = brief.topic_type      || 'YOUR_DEFAULT_TOPIC';
const primarySubject = brief.primary_subject || 'YOUR_DEFAULT_HEADLINE';
const targetAudience = brief.target_audience || 'YOUR_DEFAULT_AUDIENCE';
const tone           = brief.tone            || 'YOUR_DEFAULT_TONE';
const cta            = brief.cta             || 'YOUR_DEFAULT_CTA';
const priceHook      = brief.priceHook       || brief.price_hook   || 'YOUR_DEFAULT_PRIMARY_HOOK';
const outcomeHook    = brief.outcomeHook      || brief.outcome_hook || 'YOUR_DEFAULT_OUTCOME_HOOK';

// key_facts — handles string or array
const keyFactsRaw = Array.isArray(brief.key_facts)
  ? brief.key_facts
  : String(brief.key_facts || '').split(/[,\n]/).map(s => s.trim()).filter(Boolean);

// supportPoints — handles string, array, or falls back to key_facts
const supportPointsRaw = Array.isArray(brief.supportPoints)
  ? brief.supportPoints
  : Array.isArray(brief.support_points)
    ? brief.support_points
    : String(brief.supportPoints || brief.support_points || '')
        .split(/[,\n]/).map(s => s.trim()).filter(Boolean);

const supportPoints = (supportPointsRaw.length ? supportPointsRaw : keyFactsRaw)
  .map(v => String(v).trim().toUpperCase())
  .filter(Boolean)
  .slice(0, 4);

while (supportPoints.length < 4) supportPoints.push('');

// ─── Style context ─────────────────────────────────────────────────────────

const styleHint = designDirection
  ? `MASTER DESIGN DIRECTION: ${designDirection}`
  : styleProfile && Object.keys(styleProfile).length
    ? `Style inspiration only — never copy layout or branding: ${JSON.stringify(styleProfile)}`
    : '';

const upgradeHint = creativeUpgrades && Object.keys(creativeUpgrades).length
  ? `Apply these creative upgrades:
- Visual trend: ${creativeUpgrades.visual_trend || ''}
- Color palette: ${(creativeUpgrades.suggested_color_palette || []).join(', ')}
- Depth technique: ${creativeUpgrades.depth_technique || ''}
- Background style: ${creativeUpgrades.background_style || ''}
- Mood: ${creativeUpgrades.mood_upgrade || ''}`
  : '';

// ─── Sanitize text — remove emojis that break GPT image API ───────────────

function sanitize(text) {
  if (!text) return '';
  return String(text)
    .replace(/[\u{1F000}-\u{1FFFF}]/gu, '')
    .replace(/[\u{2700}-\u{27BF}]/gu, '')
    .replace(/[\u{2600}-\u{26FF}]/gu, '')
    .replace(/\u2705/gu, '')
    .replace(/[\u{1F300}-\u{1F9FF}]/gu, '')
    .trim();
}

// ─── Build the prompt ──────────────────────────────────────────────────────

const prompt = `
Create a premium, high-converting Instagram feed advertisement for YOUR_BUSINESS_TYPE.

CAMPAIGN OBJECTIVE:
Stop the scroll instantly. Create immediate aspiration and drive inquiries from ${sanitize(targetAudience)}.
This must feel like a top-performing Meta ad — not a flyer, not a brochure.

OFFER PSYCHOLOGY:
The viewer must instantly understand three things:
1. What is the offer? — ${sanitize(primarySubject)}
2. Why now? — ${sanitize(priceHook)}
3. What do I gain? — ${sanitize(outcomeHook)}

TOPIC:
${sanitize(topicType)}

TONE:
${sanitize(tone)}

${styleHint}
${upgradeHint}

VISUAL SUBJECT:
- Feature ONE YOUR_SUBJECT who represents "${sanitize(targetAudience)}".
- Natural expression, premium editorial photography, luxury cinematic lighting.
- Background should fit YOUR_BRAND_SETTING.
- Soft cinematic blur, premium atmosphere, zero clutter.
- Avoid stock-photo look — this must feel like a real campaign shoot.

LOGO PLACEMENT — CRITICAL:
- The attached image is the EXACT company logo — use it precisely as provided.
- Do NOT redraw, recreate, hallucinate, recolor, or stylize the logo in any way.
- Place the EXACT attached logo in the TOP-LEFT or TOP-RIGHT corner.
- Use proper padding — logo should feel premium and balanced, not squeezed.
- Choose a background color or region behind the logo that gives maximum contrast.
- The logo must be clearly readable at Instagram feed size.

COMPOSITION:
- Square 1:1 Instagram format
- Strong single focal point
- Generous whitespace
- Premium visual hierarchy
- Everything must be readable at mobile screen size

LAYOUT (strict top to bottom):
TOP     → Exact logo anchored top-left or top-right
CENTER  → Hero student + large bold main headline
MIDDLE  → WOW FACTOR: "${sanitize(priceHook)}" in largest highlight area
          SECONDARY: "${sanitize(outcomeHook)}"
BOTTOM  → 4 short benefit badges + CTA button

RENDER THIS TEXT EXACTLY (no paraphrasing, no changes):
- Main headline:  "${sanitize(primarySubject)}"
- WOW badge:      "${sanitize(priceHook)}"
- Outcome badge:  "${sanitize(outcomeHook)}"
- Benefit 1:      "${sanitize(supportPoints[0])}"
- Benefit 2:      "${sanitize(supportPoints[1])}"
- Benefit 3:      "${sanitize(supportPoints[2])}"
- Benefit 4:      "${sanitize(supportPoints[3])}"
- CTA button:     "${sanitize(cta)}"

TEXT STYLE:
- Very large bold headline — dominant and immediate
- Short badge text — all caps, high contrast
- No paragraphs, no body copy, no small print
- Maximum readability at a glance
- Luxury social media typography

DESIGN STYLE:
- Premium vivid gradients — no flat or muted backgrounds
- Cinematic editorial lighting on the student
- Glassmorphism or liquid-glass highlight cards for badges
- Layered depth — shadows, translucent overlapping shapes
- Clean whitespace that breathes
- Emotional visual storytelling
- Commercial advertising quality — award-winning feel

HARD CONSTRAINTS:
- No brochure design
- No crowded layout
- No small unreadable text
- No watermarks
- No gibberish or placeholder text
- No spelling mistakes
- No distorted anatomy or extra fingers
- No duplicated elements
- No template look
- No logo recreation — use ONLY the exact attached logo
