}];

const input = $input.first();
const brief = $('Build Openai Payload').first().json.brief;
const styleJson = $('Build Openai Payload').first().json.style_profile_json_string;
const today = new Date().toISOString().split('T')[0];
const filename = `post_${today}_${(brief.primary_subject || 'post')
  .replace(/[^a-zA-Z0-9]/g, '_').slice(0, 40)}.png`;

// Native node stores image as binary reference — pass it through directly
return [{
  json: {
    brief,
    style_profile_json_string: styleJson,
    filename,
    today,
    row_number: brief.row_number,
    image_model: "openai"
  },
  binary: {
    data: input.binary.data  // pass the binary reference as-is
  }
}];

const response = $input.first().json;

// ─── 1. Prompt blocked before generation ───────────────────────────────────
if (!response.candidates || !response.candidates[0]) {
  const blockReason = response.promptFeedback?.blockReason;
  throw new Error(
    blockReason
      ? `Image prompt blocked by Gemini: ${blockReason}`
      : `Image generation failed. Response: ${JSON.stringify(response).slice(0, 500)}`
  );
}

const candidate = response.candidates[0];
const parts = candidate.content?.parts || [];

// ─── 2. Pick the final image (skip interim "thought" images) ───────────────
const imageParts = parts.filter(p => (p.inline_data || p.inlineData) && !p.thought);
const imagePart  = imageParts[imageParts.length - 1];

if (!imagePart) {
  const textReply = parts.filter(p => p.text).map(p => p.text).join(' ').slice(0, 300);
  throw new Error(
    `Gemini returned no image. finishReason: ${candidate.finishReason || 'unknown'}` +
    (textReply ? ` | Model said: ${textReply}` : '')
  );
}

const inline   = imagePart.inline_data || imagePart.inlineData;
const imageData = inline.data;
const mimeType  = inline.mime_type || inline.mimeType || 'image/png';

if (!imageData || imageData.length < 1000) {
  throw new Error('Gemini returned an empty or invalid image.');
}

// ─── 3. Context + filename ─────────────────────────────────────────────────
const parsed    = $('Parse Style Profile').first().json;
const brief     = parsed.brief || {};
const styleJson = parsed.style_profile_json_string;

const now   = new Date();
const today = now.toISOString().split('T')[0];
const time  = now.toISOString().slice(11, 16).replace(':', '');   // HHMM UTC

const ext = mimeType.includes('jpeg') || mimeType.includes('jpg') ? 'jpg'
          : mimeType.includes('webp') ? 'webp'
          : 'png';

const slug = String(brief.primary_subject || 'post')
  .replace(/[^a-zA-Z0-9]+/g, '_')
  .replace(/^_|_$/g, '')
  .slice(0, 40);

const postNo   = brief['post#'] ? `p${brief['post#']}_` : '';
const filename = `post_${postNo}${today}_${time}_${slug}.${ext}`;

// ─── 4. Binary output ──────────────────────────────────────────────────────
let binaryData;
try {
  binaryData = await this.helpers.prepareBinaryData(
    Buffer.from(imageData, 'base64'), filename, mimeType
  );
} catch (e) {
  // Fallback for environments without helpers
  binaryData = { data: imageData, mimeType, fileName: filename, fileExtension: ext };
}

return [{
  json: {
    brief,
    style_profile_json_string: styleJson,
    filename,
    today,
    row_number: brief.row_number,
    image_model: 'nano_banana',
  },
  binary: { data: binaryData },
}];

return [{
  json: {
    message: "Regenerating your post — a new version will arrive in your inbox shortly.",
    date: $('Consolidate Results').first().json.date
  }
}];

const error = $input.first().json;

// Extract error details
